import React from 'react';
import { render, screen } from '@testing-library/react';
import BeesForce from './BeesForce';

describe('BeesForce', () => {
  test('should render without crashing', () => {
    render(<BeesForce />);
    expect(screen.getByTestId('BeesForceIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<BeesForce variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Force Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<BeesForce variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Force Vertical Logo')).toBeInTheDocument();
  });
});
